#include "KS/SRC/stringx.h"

typedef float time_value_t;

class color32 {
public:
    unsigned int value;
};

class Font {
public:
    enum HORIZJUST { HORIZJUST_LEFT, HORIZJUST_CENTER };
    enum VERTJUST { VERTJUST_TOP, VERTJUST_CENTER };
};

class FEManager {
    char padding0[0x771c];
public:
    Font font_hand;
    char padding1[0x4a4c];
    Font font_bold;
    char padding2[0x94c0];
    color32 col_unselected;
    color32 col_highlight2;
    color32 col_highlight;
    color32 white;
};

class FEMenu;
class FEMenuEntry;

class FEMenuSystem {
    char padding[0x78];
public:
    FEManager *manager;
};

class TextString {
public:
    TextString(Font *, stringx, float, float, int, float,
               Font::HORIZJUST, Font::VERTJUST, bool, color32);
};

class FEMenu {
public:
    int center_x;
    int center_y;
    int num_entries;
    int dy;
    int half;
    int menu_num;
    bool init;
    stringx font_filename;
    color32 color;
    color32 color_high;
    color32 color_high_alt;
    float scale;
    float scale_high;
    int max_vis_entries;
    int flags;
    FEMenuEntry *entries;
    FEMenuEntry *first_vis_entry;
    FEMenuEntry *last_vis_entry;
    FEMenuEntry *highlighted;
    FEMenuSystem *system;
    FEMenu *back;
    int back_num;
    FEMenu *submenus;
    FEMenu *active;
    FEMenu *parent;
    TextString *helpText;
    int helpFlags;
    FEMenu *next_sub;

    FEMenu(FEMenuSystem *, int, int);
    virtual ~FEMenu();
    virtual void setBack(FEMenu *, int = 1);
    virtual void setHigh(FEMenuEntry *, bool = true);
    virtual void setVis(FEMenuEntry *);
    virtual void Add(FEMenuEntry *);
    virtual void Init();
    virtual void Load(bool);
    virtual void Load();
    virtual void Draw();
    virtual void DrawTop();
    virtual void UpdateInScene();
    virtual void Update(time_value_t);
    virtual void HighlightDefault();
    virtual void OnActivate();
    virtual void OnActivate(int);
    virtual void OnUnactivate(FEMenu *);
    virtual void OnSelect(int);
    virtual void OnStart(int);
    virtual void OnUp(int);
    virtual void OnDown(int);
    virtual void OnLeft(int);
    virtual void OnRight(int);
    virtual void OnCross(int);
    virtual void OnTriangle(int);
    virtual void OnSquare(int);
    virtual void OnCircle(int);
    virtual void OnL1(int);
    virtual void OnR1(int);
    virtual void OnL2(int);
    virtual void OnR2(int);
    virtual void OnAnyButtonPress(int, int);
    virtual void OnButtonRelease(int, int);
    virtual void SetAllScale(float);
    virtual void MakeActive(FEMenu *, bool = true);
    virtual void SetHelpText(int);
    virtual void Select(int);
};

class FEMenuEntry {
public:
    FEMenuEntry(stringx, FEMenu *, bool = false, Font * = 0);
    virtual void SetPos(float, float);
    virtual void SetFont(Font *);
};

extern stringx controller_title;
extern stringx one_player;
extern stringx two_player;
__asm__(".equ controller_title, 0x003E6A90");
__asm__(".equ one_player, 0x003E6A98");
__asm__(".equ two_player, 0x003E6AA0");

class MultiControllerMenu : public FEMenu {
public:
    enum { OnePlayerEntry, TwoPlayerEntry, NumEntries };
    FEMenuEntry *entry[NumEntries];
    TextString *title;

    MultiControllerMenu(FEMenuSystem *, int, int);
};

MultiControllerMenu::MultiControllerMenu(FEMenuSystem *s, int x, int y)
    : FEMenu(s, x, y)
{
    color = s->manager->col_unselected;
    color_high = s->manager->col_highlight;
    flags |= 0x1e;
    color_high_alt = s->manager->col_highlight2;
    scale = scale_high = 0.9f;

    entry[OnePlayerEntry] = new FEMenuEntry(one_player, this);
    entry[TwoPlayerEntry] = new FEMenuEntry(two_player, this);

    for (int i = 0; i < NumEntries; ++i)
    {
        entry[i]->SetPos(x, y + (i - 1) * 17);
        entry[i]->SetFont(&s->manager->font_hand);
        Add(entry[i]);
    }

    title = new TextString(
        &s->manager->font_bold, controller_title, 479.0f, 233.0f, 0, 0.65f,
        Font::HORIZJUST_CENTER, Font::VERTJUST_CENTER, false,
        s->manager->white);
    dy = 17;
    SetHelpText(0);
}
